from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
def put(slug,path,text):
 p=ROOT/'apps'/slug/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
atlas='quran-concept-atlas';stories='stories-of-the-prophets'
library='''import {byId,read,write,esc,copy,announce} from './utils';
const all=[...document.querySelectorAll<HTMLElement>('[data-item-id]')];
const valid=(v:unknown):v is string[]=>Array.isArray(v)&&v.length<=100&&v.every(x=>typeof x==='string'&&/^[a-z-]{1,60}$/.test(x));
let saved=read('bookmarks',valid)||[];
function update(){document.querySelectorAll<HTMLButtonElement>('[data-save]').forEach(b=>{const yes=saved.includes(b.dataset.save!);b.textContent=yes?'Saved ✓':'Save reading';b.setAttribute('aria-pressed',String(yes));});filter();}
function filter(){const query=(document.querySelector<HTMLInputElement>('#filter')?.value||'').toLowerCase();const category=document.querySelector<HTMLSelectElement>('#category')?.value||'';const only=document.querySelector<HTMLInputElement>('#saved-only')?.checked;let n=0;all.forEach(c=>{const show=(!query||c.textContent!.toLowerCase().includes(query))&&(!category||c.dataset.category===category)&&(!only||saved.includes(c.dataset.itemId!));c.hidden=!show;if(show)n++;});const count=document.querySelector('#count');if(count)count.textContent=`${n} of ${all.length} shown`;const empty=document.querySelector<HTMLElement>('#empty');if(empty)empty.hidden=n!==0;}
document.querySelectorAll<HTMLButtonElement>('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save!;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];if(!write('bookmarks',saved))announce('Storage unavailable. Saved for this visit only.');update();});
document.querySelector('#filter')?.addEventListener('input',filter);document.querySelector('#category')?.addEventListener('change',filter);document.querySelector('#saved-only')?.addEventListener('change',filter);
document.querySelector('#export')?.addEventListener('click',()=>{const links=[...document.querySelectorAll<HTMLAnchorElement>('[data-reading-link]')].filter(a=>saved.includes(a.dataset.readingLink!));if(!links.length){announce('Save a reading first.');return;}copy('# My reading list\\n\\n'+links.map(a=>`- [${a.textContent?.trim()}](${location.origin+a.getAttribute('href')})`).join('\\n'),'Reading list copied');});update();
'''
for slug in [atlas,stories]:put(slug,'src/lib/library.ts',library)
put(atlas,'src/pages/index.astro','''---
import Shell from '../layouts/Shell.astro';
import {topics} from '../data/content.json';
---
<Shell title="Quran Concept Atlas"><section class="intro"><span class="eyebrow">One passage opens another</span><h1>Follow a thread<br/>through the Quran.</h1><p>Explore 30 themes, 90 selected passages, and connections you can follow at your own pace.</p></section><div class="notice bottom-gap"><p>These themes and learning paths are editorial guides. They do not replace reading a passage in its full context.</p></div><section class="panel bottom-gap"><div class="panel-body"><div class="filters"><label class="field">Find a theme<input type="search" id="filter" placeholder="Patience, prayer, justice…"/></label><label class="field">Area<select id="category"><option value="">All areas</option>{['Character','Community','Reflection','Worship'].map(g=><option>{g}</option>)}</select></label><label><input type="checkbox" id="saved-only"/> Saved only</label><button class="button secondary" id="export">Copy saved reading list</button></div><p class="micro" id="count" aria-live="polite"></p></div></section><div class="card-grid">{topics.map(t=><article class="panel activity-card" data-item-id={t.id} data-category={t.category}><span class="eyebrow">{t.category}</span><h2><a href={`/topic/${t.id}/`} data-reading-link={t.id}>{t.theme}</a></h2><p>{t.explanation}</p><span class="micro">{t.refs.join(' · ')}</span><div class="actions"><a class="button" href={`/topic/${t.id}/`}>Explore theme ↗</a><button class="button secondary" data-save={t.id} aria-pressed="false">Save reading</button></div></article>)}</div><div id="empty" class="empty" hidden><h2>No themes match</h2><p>Try another word, change the area, or turn off Saved only.</p></div><script>import '../lib/library';</script></Shell>
''')
put(atlas,'src/pages/topic/[id].astro','''---
import Shell from '../../layouts/Shell.astro';
import {topics} from '../../data/content.json';
export function getStaticPaths(){return topics.map(topic=>({params:{id:topic.id},props:{topic}}));}
const {topic}=Astro.props;const related=topics.filter(t=>topic.related.includes(t.id));
---
<Shell title={topic.theme}><a class="back-link" href="/">← All themes</a><section class="intro"><span class="eyebrow">{topic.category} · selected readings</span><h1>{topic.theme}</h1><p>{topic.explanation}</p><button class="button secondary" data-save={topic.id} aria-pressed="false">Save reading</button></section><div class="workspace"><section>{topic.passages.map((p,i)=><article class="panel bottom-gap"><div class="panel-head"><h2>Reading {i+1} · {p.ref}</h2><a href={p.translationUrl} target="_blank" rel="noopener noreferrer">Read context ↗</a></div><div class="panel-body"><p class="arabic" lang="ar" dir="rtl">{p.arabic}</p><blockquote class="source-quote">{p.translation}</blockquote><p class="micro">Marmaduke Pickthall · Quran {p.ref}</p></div></article>)}</section><aside class="sidebar"><div class="panel panel-body"><span class="eyebrow">Keep exploring</span><h2>Connected readings</h2><div class="topic-map"><span class="map-center">{topic.theme}</span>{related.map(t=><a href={`/topic/${t.id}/`}>{t.theme} ↗</a>)}</div><p class="micro">Editorial paths within the same study area. Connections are suggestions, not an exclusive Quranic taxonomy.</p></div><div class="notice"><h2>Commentary</h2><p>Read the concise Arabic commentary for the anchor passage.</p><a href={topic.commentaryUrl} target="_blank" rel="noopener noreferrer">Al-Tafsir al-Muyassar ↗</a></div></aside></div><script>import '../../lib/library';</script></Shell>
<style>.topic-map{display:grid;gap:12px;padding:10px 0}.topic-map a{border-left:2px solid var(--accent);margin-left:20px;padding:8px 14px;background:var(--tint);border-radius:0 8px 8px 0}.map-center{padding:15px;border:1px solid var(--accent);border-radius:12px;font-weight:600;text-align:center}</style>
''')
put(stories,'src/pages/index.astro','''---
import Shell from '../layouts/Shell.astro';
import {people} from '../data/content.json';
const sorted=[...people].sort((a,b)=>a.name.localeCompare(b.name));
---
<Shell title="Stories of the Prophets Explorer"><section class="intro"><span class="eyebrow">Read the Quranic account</span><h1>Names you know.<br/>Passages to explore.</h1><p>25 named prophets. 50 selected readings. Open a profile, read the source, and check what you noticed.</p></section><div class="notice bottom-gap"><p>This is a selected reading library, not a complete biography collection. Profiles are alphabetical; no historical order is implied. Brief mentions are presented without adding an unsourced life story.</p></div><section class="panel bottom-gap"><div class="panel-body filters"><label class="field">Find a prophet or reading<input id="filter" type="search" placeholder="Musa, gratitude, patience…"/></label><label class="field">Reading area<select id="category"><option value="">All areas</option>{[...new Set(people.map(p=>p.category))].sort().map(g=><option>{g}</option>)}</select></label><label><input type="checkbox" id="saved-only"/> Saved only</label><button class="button secondary" id="export">Copy saved reading list</button><span class="micro" id="count" aria-live="polite"></span></div></section><div class="card-grid">{sorted.map((p)=><article class="panel activity-card" data-item-id={p.id} data-category={p.category}><span class="eyebrow">{p.category}</span><h2><a href={`/prophet/${p.id}/`} data-reading-link={p.id}>{p.name}</a></h2><p>{p.focus}</p><span class="micro">{p.readings.map(r=>r.ref).join(' · ')}</span><div class="actions"><a class="button" href={`/prophet/${p.id}/`}>Open readings ↗</a><button class="button secondary" data-save={p.id} aria-pressed="false">Save reading</button></div></article>)}</div><div class="empty" id="empty" hidden><h2>No profiles match</h2><p>Try another name or reading focus, or turn off Saved only.</p></div><script>import '../lib/library';</script></Shell>
''')
put(stories,'src/pages/prophet/[id].astro','''---
import Shell from '../../layouts/Shell.astro';
import {people} from '../../data/content.json';
export function getStaticPaths(){return people.map(person=>({params:{id:person.id},props:{person}}));}
const {person}=Astro.props;const next=people[(people.findIndex(p=>p.id===person.id)+1)%people.length];
---
<Shell title={person.name}><a href="/" class="back-link">← All profiles</a><section class="intro"><span class="eyebrow">{person.category} · selected Quran readings</span><h1>{person.name}</h1><p>{person.focus}</p><button class="button secondary" data-save={person.id} aria-pressed="false">Save reading</button></section>{person.brief&&<div class="notice bottom-gap"><p>The Quran mentions {person.name} briefly in these passages. This profile makes no claim about dates, locations, or a fuller biography beyond the cited text.</p></div>}<div class="workspace"><section>{person.readings.map((r,i)=><article class="panel bottom-gap" id={`reading-${i+1}`}><div class="panel-head"><h2>Reading {i+1} · Quran {r.ref}</h2><a href={r.translationUrl} target="_blank" rel="noopener noreferrer">Read context ↗</a></div><div class="panel-body"><p class="arabic" lang="ar" dir="rtl">{r.arabic}</p><blockquote class="source-quote">{r.translation}</blockquote><p class="micro">Marmaduke Pickthall · historical English wording</p></div></article>)}</section><aside class="sidebar"><section class="panel panel-body"><span class="eyebrow">Pause and notice</span><h2>Reading check</h2><p>{person.question}</p><form id="quiz" data-answer={person.answer}><fieldset><legend class="sr-only">Choose a reading focus</legend>{person.options.map((option,i)=><label style="display:block;margin:14px 0"><input type="radio" name="answer" value={i} required/> {option}</label>)}</fieldset><button class="button">Check answer</button><p id="feedback" role="status"></p></form><p class="micro">An editorial comprehension exercise. The reading focus is not a complete interpretation.</p></section><div class="notice"><h2>Keep reading</h2><a href={`/prophet/${next.id}/`}>Next profile: {next.name} ↗</a><p>Library sequence only; it does not indicate chronology.</p></div></aside></div><script>import '../../lib/library';import '../../lib/quiz';</script></Shell>
''')
put(stories,'src/lib/quiz.ts', '''import {byId} from './utils';
const form=byId<HTMLFormElement>('quiz');form.onsubmit=e=>{e.preventDefault();const selected=new FormData(form).get('answer');const yes=selected===form.dataset.answer;byId('feedback').textContent=yes?'That focus fits these readings. Revisit the passages to notice the details.':'Read the two passages again, then choose the focus that fits both. You can try again.';};
''')
